const linha = $input.first().json;
const faltas = linha.faltas || [];
const pendencias = linha.pendencias || [];

function fmtData(iso) {
  const [ano, mes, dia] = iso.split('-');
  return `${dia}/${mes}`;
}

const partes = ['📦 *Faltas e pendências*', ''];

partes.push(`🚫 *Produtos em falta (últimos 2 dias)* — ${faltas.length}`);
if (faltas.length === 0) {
  partes.push('Nenhum registrado.');
} else {
  faltas.forEach((f) => {
    partes.push(`• ${f.nome_produto} — ${fmtData(f.data)} (${f.registrado_por})`);
  });
}
partes.push('');

partes.push(`🗒️ *Pendências em aberto* — ${pendencias.length}`);
if (pendencias.length === 0) {
  partes.push('Nenhuma pendência em aberto.');
} else {
  pendencias.forEach((p) => {
    const dias = p.dias_aberta;
    const alerta = dias >= 7 ? ' ⚠️' : '';
    partes.push(`• ${p.nome_cliente} — ${p.produtos} (${dias}d aberta${alerta}, ${p.registrado_por})`);
  });
}

return [{ json: { mensagem: partes.join('\n').trim() } }];
